/** 
 * returns a type's element size in bits.
 */
static int typeSize(TypeKind kind){
    try {
        switch (kind) {
        case BOOLEAN:    return 1;
        case BYTE:  return 8;
        case SHORT:return 16;
        case FLOAT:case CHAR:case INT:return 32;
        case LONG:case DOUBLE:return 64;
        default:throw new IllegalArgumentException("Invalid type kind: " + kind);
        }
    } catch (IllegalArgumentException e) {
        // Handle the exception, e.g., log the error or return a default value
        System.err.println("Caught exception: " + e.getMessage());
        return -1; // Indicate an error with a special value
    }
}
